export default "import {\n  SceneGridLayout,\n  SceneGridRow,\n  SceneGridItem,\n  SceneAppPage,\n  EmbeddedScene,\n  SceneAppPageState,\n  PanelBuilders,\n} from '@grafana/scenes';\nimport { getEmbeddedSceneDefaults, getQueryRunnerWithRandomWalkQuery } from './utils';\n\nexport function getGridWithRowLayoutTest(defaults: SceneAppPageState): SceneAppPage {\n  return new SceneAppPage({\n    ...defaults,\n    getScene: () => {\n      return new EmbeddedScene({\n        ...getEmbeddedSceneDefaults(),\n        $data: getQueryRunnerWithRandomWalkQuery(),\n        body: new SceneGridLayout({\n          isDraggable: true,\n          children: [\n            new SceneGridRow({\n              title: 'Row A',\n              key: 'Row A',\n              isCollapsed: true,\n              isDraggable: true,\n              isResizable: false,\n              y: 0,\n              x: 0,\n              children: [\n                new SceneGridItem({\n                  x: 0,\n                  y: 1,\n                  width: 12,\n                  height: 5,\n                  isResizable: true,\n                  isDraggable: true,\n                  body: PanelBuilders.timeseries().setTitle('Row A Child1').build(),\n                }),\n                new SceneGridItem({\n                  x: 0,\n                  y: 5,\n                  width: 6,\n                  height: 5,\n                  isResizable: true,\n                  isDraggable: true,\n                  body: PanelBuilders.timeseries().setTitle('Row A Child2').build(),\n                }),\n              ],\n            }),\n            new SceneGridRow({\n              title: 'Row B',\n              key: 'Row B',\n              isCollapsed: true,\n              y: 1,\n              children: [\n                new SceneGridItem({\n                  x: 0,\n                  y: 2,\n                  width: 12,\n                  height: 5,\n                  isResizable: false,\n                  isDraggable: true,\n                  body: PanelBuilders.timeseries().setTitle('Row B Child1').build(),\n                }),\n                new SceneGridItem({\n                  x: 0,\n                  y: 7,\n                  width: 6,\n                  height: 5,\n                  isResizable: false,\n                  isDraggable: true,\n                  body: PanelBuilders.timeseries().setTitle('Row B Child2').build(),\n                }),\n              ],\n            }),\n            new SceneGridItem({\n              x: 2,\n              y: 12,\n              width: 12,\n              height: 10,\n              isResizable: true,\n              isDraggable: true,\n              body: PanelBuilders.timeseries().setTitle('Outsider').build(),\n            }),\n          ],\n        }),\n      });\n    },\n  });\n}\n";